( SELECT subject, predicate, object FROM eswanson_demo.ontobricks.triplestore_clinicaldomain_v3 WHERE NOT (predicate = 'https://care-protocol.example/ontology/hasIngredient' AND object LIKE 'https://care-protocol.example/ontology/ing/DRUGCLASS-%') AND predicate <> 'https://care-protocol.example/ontology/inDrugClass' UNION ALL SELECT concat('https://care-protocol.example/ontology/ing/', code), 'https://care-protocol.example/ontology/inDrugClass', concat('https://care-protocol.example/ontology/DrugClass/', parent_code) FROM eli_test_classic_catalog.care_protocol_terminology.rxnorm_hier WHERE relationship = 'class_member' UNION ALL SELECT concat('https://care-protocol.example/ontology/icd/', code), 'http://www.w3.org/2000/01/rdf-schema#label', max(name) FROM eli_test_classic_catalog.care_protocol_terminology.icd10_hier GROUP BY code UNION ALL SELECT concat('https://care-protocol.example/ontology/rx/', rx), 'http://www.w3.org/2000/01/rdf-schema#label', max(nm) FROM ( SELECT code AS rx, name AS nm FROM eli_test_classic_catalog.care_protocol_terminology.rxnorm_hier WHERE relationship = 'ingredient_of' UNION ALL SELECT rxnorm_code, description FROM eli_test_classic_catalog.care_protocol.bronze_order_med WHERE rxnorm_code IS NOT NULL) m GROUP BY rx UNION ALL SELECT concat('https://care-protocol.example/ontology/ing/', code), 'http://www.w3.org/2000/01/rdf-schema#label', max(name) FROM eli_test_classic_catalog.care_protocol_terminology.rxnorm_hier WHERE relationship = 'class_member' GROUP BY code UNION ALL SELECT concat('https://care-protocol.example/ontology/DrugClass/', code), 'http://www.w3.org/2000/01/rdf-schema#label', max(name) FROM eli_test_classic_catalog.care_protocol_terminology.rxnorm_hier WHERE code LIKE 'DRUGCLASS-%' GROUP BY code UNION ALL SELECT concat('https://care-protocol.example/ontology/ValueSet/', segment_id), 'http://www.w3.org/2000/01/rdf-schema#label', max(segment_name) FROM eli_test_classic_catalog.care_protocol_terminology.value_set_segment GROUP BY segment_id ) sim